  assert.doesNotMatch(fallback.memory.summary.aiText, /events|actions|observations|runId|operation|af5b513f|mock-model|不得进入摘要/u);
  const nested = await direct({ response: { data: { result: { description: '裴晚生在门口停下。' } } } });
