test('千事预览遇到待同步正文或孤儿锚只读拒绝，修复仍走记忆管理刷新入口', async t => {
  for (const fault of ['pendingSync', 'orphanAnchor']) await t.test(fault, async () => {
    const seed = harness({ modernAnchors: true,
      initialChat: [user('开始'), assistant('顾舟答应归还旧书。'), user('稳定')],
      persistAnchors: async ({ chatId, bindings }) => { for (const binding of bindings) {
        const message = seed.context.chat[binding.messageIndex]; message.extra ??= {};
        message.extra.qianqianjie_floor = { schemaVersion: 1, chatId, floorId: binding.floorId };
      } },
      utility: options => options.systemPrompt === EXTRACTOR_SYSTEM_PROMPT
        ? { jsonData: { summary: '已有摘要。', qianshi: { events: [{ key: 'event-1', title: '归还旧书',
          description: '顾舟答应归还旧书', status: 'planned', matter: true }], order: [] } } }
        : { jsonData: { noMaterialChange: true } } });
    await seed.runtime.start();
    await seed.runtime.extractFloor(seed.runtime.getState().floors[0].floorId, { analyzeState: false });
    if (fault === 'pendingSync') {
      seed.context.chat.push(assistant('需要先同步的新稳定楼。'), user('确认新楼'));
    } else {
      seed.context.chat[1].extra ??= {};
      seed.context.chat[1].extra.qianqianjie_floor = { schemaVersion: 1, chatId: CHAT, floorId: 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee' };
    }
    const h = harness({ modernAnchors: true, readOnlyLifecycle: true, sharedBackend: seed.backend, sharedContext: seed.context });
    await h.runtime.start();
    const putsBefore = h.backend.calls.filter(call => call[0] === 'put').length;
    const callsBefore = h.calls.length;
    await assert.rejects(h.runtime.prepareQianshiHistory(), error => error?.code === 'V3_MEMORY_FOUNDATION_NOT_READY');
    assert.equal(h.backend.calls.filter(call => call[0] === 'put').length, putsBefore, `${fault} 只读预览不得提交 foundation 或 anchor`);
    assert.equal(h.calls.length, callsBefore, `${fault} 只读预览不得调用 API`);
  });
});

test('历史同批跨楼 context/order 保留，无效一次性 progress 只拒绝受影响楼', async t => {
  for (const kind of ['context', 'progress']) await t.test(kind, async () => {
    let mode = 'summary';
    const h = harness({ initialChat: [user('历史来源输入'), assistant('第一楼记下一次性事件。'), user('第二楼来源输入'), assistant('第二楼补充相关事实。'), user('稳定')],
      utility: options => {
        if (mode === 'history') {
          const request = JSON.parse(options.taskMessages[0].content);
          assert.equal(request.floors.length, 2);
          assert.match(JSON.stringify(request.floors[0].sourceUserInputSnapshot), /历史来源输入/u, '请求使用落盘的旧楼 USER 快照');
          assert.match(options.systemPrompt, /只有计划、持续事项 matter=true/u);
          return { jsonData: { floors: request.floors.map((value, index) => ({ floorKey: value.floorKey, qianshi: { events: index === 0
            ? [{ key: 'fact', title: '一次性旧事实', description: '第一楼发生一件独立事实', status: 'occurred', matter: false }]
            : [{ key: 'followup', title: '旧事实补充', description: '第二楼补充先前事实', status: 'occurred',
              links: [{ candidateKey: 'floor-1:fact', kind }] }],
          order: index ? [{ before: 'floor-1:fact', after: 'followup' }] : [] } })) } };
        }
        const request = JSON.parse(options.taskMessages[0].content);
        return request.task === 'extractFloorSemantics' ? { jsonData: { summary: '已存在的楼摘要。' } } : { jsonData: { noMaterialChange: true } };
      } });
    await h.runtime.start();
    for (const floor of h.runtime.getState().floors) await h.runtime.extractFloor(floor.floorId, { analyzeState: false });
    const plan = await h.runtime.prepareQianshiHistory();
    assert.equal(plan.batchCount, 1);
    mode = 'history';
    const result = await h.runtime.startQianshiHistory(plan.planId);
    if (kind === 'progress') {
      const outcome = result.outcomes.find(item => item.floorId === h.runtime.getState().floors[1].floorId);
      assert.equal(outcome.reasonCode, 'QIANSHI_HISTORY_DELTA_PENDING', '唯一事件有无效 progress 时给出本楼反馈');
    }
    assert.equal(h.calls.at(-1).maxTokens, plan.maxOutputTokens, 'completion 上限通过 max_tokens 单独传递');
    const saved = await h.store.readReachable({ mode: 'runtime' });
    const firstDelta = saved.floorMemories.find(memory => memory.floorId === h.runtime.getState().floors[0].floorId).qianshiDelta;
    const secondDelta = saved.floorMemories.find(memory => memory.floorId === h.runtime.getState().floors[1].floorId).qianshiDelta;
    assert.ok(firstDelta.events[0].matterId, '一次性事件保留自己的内部 singleton 线 ID');
    assert.equal(firstDelta.events[0].updatesMatter, false);
    if (kind === 'progress') {
      assert.equal(result.status, 'partial');
      assert.equal(secondDelta.status, 'pending', '坏候选不变成一个新的独立事项');
      assert.equal(secondDelta.events.length, 0);
    } else {
      assert.equal(result.status, 'completed', JSON.stringify({ outcomes: result.outcomes, delta: secondDelta }));
      assert.equal(secondDelta.status, 'ready');
      assert.deepEqual(secondDelta.events[0].continuesFromEventIds, [firstDelta.events[0].id]);
      assert.deepEqual(secondDelta.relations.map(relation => [relation.type, relation.fromEventId, relation.toEventId]),
        [['before', firstDelta.events[0].id, secondDelta.events[0].id]]);
      assert.equal(projectQianshiGraph(saved).diagnostics.degradedFloorIds.length, 0);
    }
  });
});

test('同批前楼新事件绑定可供后楼引用并成功保存', async () => {
  let mode = 'summary';
  const seed = harness({ initialChat: [user('开始'), assistant('第一楼新约定。'), assistant('第二楼继续这项约定。'), user('稳定')],
    utility: options => mode === 'summary' ? { jsonData: { summary: '已有摘要。' } } : { jsonData: { noMaterialChange: true } } });
  await seed.runtime.start();
  for (const floor of seed.runtime.getState().floors) await seed.runtime.extractFloor(floor.floorId, { analyzeState: false });
  const before = await seed.store.readReachable({ mode: 'runtime' });
  for (const memory of before.floorMemories) {
    const key = `chat-${CHAT}/v3-floor-memory-${memory.id}`, stored = seed.backend.records.get(key);
    const { qianshiDelta: _oldDelta, ...legacyData } = stored.data;
    seed.backend.records.set(key, { ...stored, data: legacyData });
  }
  const history = harness({ sharedBackend: seed.backend, sharedContext: seed.context,
    utility: options => {
      const request = JSON.parse(options.taskMessages[0].content);
      const second = request.floors.find(value => value.assistantSeq === 2);
      assert.ok(second, '同一批包含后楼');
      assert.deepEqual(second.qianshiCandidateKeys, [], '请求候选池开始时没有旧事项');
      return { jsonData: { floors: request.floors.map(value => value.assistantSeq === 1
        ? { floorKey: value.floorKey, qianshi: { events: [{ key: 'new', title: '新约定', description: '第一楼建立新约定', status: 'planned', matter: true }], order: [] } }
        : { floorKey: value.floorKey, qianshi: { events: [{ key: 'continue', title: '继续新约定', description: '第二楼继续第一楼约定',
          status: 'inProgress', matter: true, links: [{ candidateKey: 'floor-1:new', kind: 'progress' }] }], order: [] } }) } };
    } });
  await history.runtime.start();
  const plan = await history.runtime.prepareQianshiHistory();
  assert.equal(plan.batchCount, 1);
  mode = 'history';
  const result = await history.runtime.startQianshiHistory(plan.planId);
  assert.equal(result.status, 'completed');
  const after = await history.store.readReachable({ mode: 'runtime' });
  assert.equal(projectQianshiGraph(after).relations.filter(relation => relation.type === 'progress').length, 1,
    '新鲜 earlierBindings 可以让同批后楼建立有效 progress 关系');
  assert.equal(projectQianshiGraph(after).diagnostics.degradedFloorIds.length, 0);
});

test('CAS 重试会在最新图验证无旧千事的历史补齐候选，前楼事件并发移除后只保存摘要', async () => {
  const initialChat = [user('开始'), assistant('顾舟计划归还旧书。'), user('确认第一楼'), assistant('顾舟带着旧书来到车站。'), user('确认第二楼')];
  const seed = harness({ initialChat, utility: options => {
    const request = JSON.parse(options.taskMessages[0].content);
    if (request.task === 'extractFloorSemantics') return request.payload.canonicalContent.includes('计划归还')
      ? { jsonData: { summary: '旧书归还计划。', qianshi: { events: [{ key: 'prior', title: '归还旧书', description: '顾舟计划归还旧书', status: 'planned', matter: true }], order: [] } } }
      : { jsonData: { summary: '车站旧摘要。' } };
    return { jsonData: { noMaterialChange: true } };
  } });
  await seed.runtime.start();
  const floors = seed.runtime.getState().floors;
  for (const floor of floors) await seed.runtime.extractFloor(floor.floorId, { analyzeState: false });
  const seeded = await seed.store.readReachable({ mode: 'runtime' });
  const legacyTarget = seeded.floorMemories.find(memory => memory.floorId === floors[1].floorId);
  const legacyKey = `chat-${CHAT}/v3-floor-memory-${legacyTarget.id}`, storedLegacy = seed.backend.records.get(legacyKey);
  const { qianshiDelta: _oldDelta, ...legacyData } = storedLegacy.data;
  seed.backend.records.set(legacyKey, { ...storedLegacy, data: legacyData });
  assert.equal((await seed.store.readReachable({ mode: 'runtime' })).floorMemories.find(memory => memory.floorId === floors[1].floorId).qianshiDelta, undefined,
    '真实旧格式 FloorMemory 确实没有千事 delta');

  const history = harness({ sharedBackend: seed.backend, sharedContext: seed.context,
    utility: async options => {
      const request = JSON.parse(options.taskMessages[0].content);
      const candidate = request.qianshiCandidates?.[0];
      assert.ok(candidate?.key, '历史请求使用最新图里的前楼事项候选');
      return { jsonData: { floors: request.floors.map(value => ({ floorKey: value.floorKey, qianshi: { events: [{
        key: 'late-progress', title: '车站归还旧书', description: '顾舟在车站归还旧书，推进旧约定', status: 'completed',
        matter: true, links: [{ candidateKey: candidate.key, kind: 'progress' }],
      }], order: [] } })) } };
    } });
  const removal = harness({ sharedBackend: seed.backend, sharedContext: seed.context,
    utility: options => options.systemPrompt === EXTRACTOR_SYSTEM_PROMPT
      ? { jsonData: { summary: '前楼更新为没有有效事件。', qianshi: { events: [], order: [] } } }
      : { jsonData: { noMaterialChange: true } } });
  await history.runtime.start(); await removal.runtime.start();
  const plan = await history.runtime.prepareQianshiHistory();
  assert.equal(plan.totalFloors, 1);
  let raced = false;
  seed.backend.setBeforePut(async ({ key }) => {
    if (!String(key).includes('v3-root') || raced) return;
    raced = true;
    const sourceFloor = removal.runtime.getState().floors[0];
    await removal.runtime.extractFloor(sourceFloor.floorId, { analyzeState: false });
  });
  const result = await history.runtime.startQianshiHistory(plan.planId);
  seed.backend.setBeforePut(null);
  assert.equal(raced, true, '历史写 root 前真实并发提交前楼更新，令首轮 CAS 冲突');
  assert.equal(result.status, 'partial', '最新图已不含被引用事件，历史千事结果拒绝而任务如实部分完成');
  const after = await history.store.readReachable({ mode: 'runtime' });
  const target = after.floorMemories.find(memory => memory.floorId === floors[1].floorId);
  assert.equal(target.summary.aiText, '车站旧摘要。', '旧目标摘要仍保留');
  assert.equal(target.qianshiDelta, undefined, '旧目标原本没有千事，新结果中的过期跨楼引用也不得落盘');
  assert.equal(after.floorMemories.find(memory => memory.floorId === floors[0].floorId).qianshiDelta.events.length, 0, 'CAS winner 确实已移除候选事件');
});

test('历史候选 CAS 重试复核事项起点与最新事件语义，未变化时正常提交', async t => {
  for (const changedEvent of ['origin', 'latest', 'none']) await t.test(changedEvent, async () => {
    const initialChat = [user('开始'), assistant('顾舟计划归还旧书。'), user('确认第一楼'),
      assistant('顾舟带着旧书来到车站。'), user('确认第二楼'), assistant('等待历史补齐。'), user('确认第三楼'),
      assistant('另一件独立的钟楼约定。'), user('确认第四楼')];
    const seed = harness({ initialChat, utility: options => {
      const request = JSON.parse(options.taskMessages[0].content);
      if (request.task !== 'extractFloorSemantics') return { jsonData: { noMaterialChange: true } };
      const content = request.payload.canonicalContent;
      if (content.includes('计划归还')) return { jsonData: { summary: '旧书归还计划。', qianshi: { events: [{
        key: 'origin', title: '归还旧书', description: '顾舟计划归还旧书', status: 'planned', matter: true,
        object: '旧书', storyTime: '六月', people: ['顾舟'],
      }], order: [] } } };
      if (content.includes('带着旧书')) {
        const candidate = request.payload.qianshiCandidates?.[0];
        return { jsonData: { summary: '车站旧摘要。', qianshi: { events: [{ key: 'latest', title: '车站推进旧约',
          description: '顾舟带着旧书来到车站，推进原计划', status: 'inProgress', matter: true,
          ...(candidate ? { links: [{ candidateKey: candidate.key, kind: 'progress' }] } : {}),
        }], order: [] } } };
      }
      if (content.includes('另一件独立')) return { jsonData: { summary: '钟楼约定摘要。', qianshi: { events: [{
        key: 'unrelated', title: '钟楼约定', description: '另一件独立的钟楼约定', status: 'planned', matter: true,
      }], order: [] } } };
      return { jsonData: { summary: '待补摘要。' } };
    } });
    await seed.runtime.start();
    const floors = seed.runtime.getState().floors;
    for (const floor of floors) await seed.runtime.extractFloor(floor.floorId, { analyzeState: false });
    const oldReachable = await seed.store.readReachable({ mode: 'runtime' });
    const unrelatedSummaryBefore = structuredClone(oldReachable.floorMemories.find(memory => memory.floorId === floors[3].floorId).summary);
    const graph = projectQianshiGraph(oldReachable);
    const matter = graph.matters.find(value => value.latestEventIds.length && value.origin.eventId !== value.latestEventIds[0]);
    assert.ok(matter, '种子图包含不同的事项起点与最新事件');
    const origin = graph.events.find(value => value.id === matter.origin.eventId);
    const latest = graph.events.find(value => value.id === matter.latestEventIds[0]);
    assert.equal(origin.matterId, latest.matterId);

    const target = oldReachable.floorMemories.find(memory => memory.floorId === floors[2].floorId);
    const targetKey = `chat-${CHAT}/v3-floor-memory-${target.id}`;
    const targetStored = seed.backend.records.get(targetKey);
    const { qianshiDelta: _oldDelta, ...legacyData } = targetStored.data;
    seed.backend.records.set(targetKey, { ...targetStored, data: legacyData });

    const history = harness({ sharedBackend: seed.backend, sharedContext: seed.context, utility: options => {
      const request = JSON.parse(options.taskMessages[0].content), candidate = request.qianshiCandidates.find(value => value.candidateType === 'matter');
      assert.ok(candidate, '请求包含持续事项候选');
      return { jsonData: { floors: request.floors.map(value => ({ floorKey: value.floorKey, events: [{
        key: 'late-progress', title: '归还旧书', description: '顾舟完成旧书归还计划', status: 'completed', matter: true,
      }], order: [{ before: candidate.key, after: 'late-progress' }] })) } };
    } });
    const concurrent = harness({ sharedBackend: seed.backend, sharedContext: seed.context });
    await history.runtime.start(); await concurrent.runtime.start();
    const plan = await history.runtime.prepareQianshiHistory();
    assert.equal(plan.totalFloors, 1);
    let raced = false;
    seed.backend.setBeforePut(async ({ key }) => {
      if (!String(key).includes('v3-root') || raced) return;
      raced = true;
      if (changedEvent !== 'none') {
        const selected = changedEvent === 'origin' ? origin : latest;
        const selectedMemory = oldReachable.floorMemories.find(memory => memory.floorId === selected.sourceFloorId);
        const memoryKey = `chat-${CHAT}/v3-floor-memory-${selectedMemory.id}`, stored = seed.backend.records.get(memoryKey);
        const changed = structuredClone(stored.data);
        const event = changed.qianshiDelta.events.find(value => value.id === selected.id);
        changed.qianshiDelta.events = changed.qianshiDelta.events.map(value => value.id === selected.id
          ? { ...value, object: '新箱子', storyTime: '七月', people: [{ entityId: null, name: '沈砚' }] } : value);
        assert.ok(event, `${changedEvent} 事件存在于其旧 FloorMemory`);
        seed.backend.records.set(memoryKey, { ...stored, data: changed });
      }
      await concurrent.runtime.editSummary(floors[3].floorId, '无关后楼并发摘要。');
    });
    const result = await history.runtime.startQianshiHistory(plan.planId);
    seed.backend.setBeforePut(null);
    assert.equal(raced, true, '无关后楼 root 提交制造真实 CAS 冲突，目标楼记录未被改动');
    const outcome = result.outcomes.find(item => item.floorId === floors[2].floorId);
    const after = await history.store.readReachable({ mode: 'runtime' });
    const savedTarget = after.floorMemories.find(memory => memory.floorId === floors[2].floorId);
    if (changedEvent === 'none') {
      assert.equal(outcome.reasonCode, null);
      assert.equal(result.status, 'completed');
      assert.equal(savedTarget.qianshiDelta.status, 'ready', '候选语义未变时 CAS 重试正常保存历史结果');
      assert.equal(savedTarget.qianshiDelta.relations.length, 1, '平铺返回的 order 候选端点被编译并提交');
    } else {
      assert.equal(outcome.reasonCode, 'QIANSHI_HISTORY_CANDIDATE_STALE', '必须由候选完整语义守卫拒绝，不能由目标楼 prefix 检查代替');
      assert.equal(result.status, 'partial');
      assert.equal(savedTarget.qianshiDelta, undefined, '过期 progress 关系不落入目标楼');
      const changed = after.floorMemories.find(memory => memory.id === oldReachable.floorMemories.find(value => value.floorId === floors[changedEvent === 'origin' ? 0 : 1].floorId).id)
        .qianshiDelta.events.find(value => value.id === (changedEvent === 'origin' ? origin.id : latest.id));
      assert.equal(changed.id, changedEvent === 'origin' ? origin.id : latest.id);
      assert.equal(changed.matterId, matter.matterId);
      assert.equal(changed.object, '新箱子'); assert.equal(changed.storyTime, '七月');
      assert.deepEqual(changed.people.map(value => value.name), ['沈砚']);
    }
    assert.notDeepEqual(after.floorMemories.find(memory => memory.floorId === floors[3].floorId).summary, unrelatedSummaryBefore,
      '无关后楼已经独立落盘，确认 CAS 冲突由候选以外的楼造成');
  });
});

test('千事历史显式停止后只重新规划未完成楼，不重发已成功楼', async () => {
  let mode = 'summary', historyCalls = 0, releaseSecond, markSecondStarted;
  const secondStarted = new Promise(resolve => { markSecondStarted = resolve; });
  const secondWait = new Promise(resolve => { releaseSecond = resolve; });
  const longA = `第一楼-${'甲'.repeat(10000)}`, longB = `第二楼-${'乙'.repeat(10000)}`;
  const historyResponse = options => {
    const request = JSON.parse(options.taskMessages[0].content);
    return { jsonData: { floors: request.floors.map(value => ({ floorKey: value.floorKey, qianshi: { events: [{ key: 'event-1', title: `事项${value.assistantSeq}`,
      description: `第${value.assistantSeq}楼事项`, status: 'planned', matter: true }], order: [] } })) } };
  };
  const h = harness({ initialChat: [user('开始'), assistant(longA), assistant(longB), user('稳定')], utility: async options => {
    if (mode === 'summary') return { jsonData: { summary: '已有摘要。' } };
    historyCalls += 1;
    if (historyCalls === 2) { markSecondStarted(); await secondWait; }
    return historyResponse(options);
  } });
  await h.runtime.start();
  for (const value of h.runtime.getState().floors) await h.runtime.extractFloor(value.floorId, { analyzeState: false });
  mode = 'history';
  const firstPlan = await h.runtime.prepareQianshiHistory({ maxInputTokens: 40000 });
  assert.equal(firstPlan.batchCount, 2, '夹具应把两楼规划为两个批次');
  const running = h.runtime.startQianshiHistory(firstPlan.planId);
  await secondStarted;
  const stopping = h.runtime.stopQianshiHistory();
  releaseSecond();
  const [stopped] = await Promise.all([running, stopping]);
  assert.equal(stopped.status, 'stopped');
  assert.equal(stopped.processedFloors, 1);
  const firstCompleted = h.runtime.getQianshiSnapshot().events.map(value => value.sourceFloorId);
  assert.equal(firstCompleted.length, 1);
  const resumePlan = await h.runtime.prepareQianshiHistory({ maxInputTokens: 40000 });
  assert.equal(resumePlan.totalFloors, 1, '重新规划只包含未完成楼');
  assert.equal(resumePlan.apiCalls, 1);
  const resumed = await h.runtime.startQianshiHistory(resumePlan.planId);
  assert.equal(resumed.status, 'completed');
  assert.equal(h.runtime.getQianshiSnapshot().coverage.completeFloors, 2);
  assert.equal(h.runtime.getQianshiSnapshot().events.filter(value => firstCompleted.includes(value.sourceFloorId)).length, 1, '已成功楼没有重复提取');
});

test('千事历史请求切换聊天后仍提交到原目标，当前页面不接收旧目标快照', async () => {
  let mode = 'summary', releaseHistory, markStarted;
  const started = new Promise(resolve => { markStarted = resolve; });
  const wait = new Promise(resolve => { releaseHistory = resolve; });
  let h;
  h = harness({ initialChat: [user('开始'), assistant('顾舟答应归还旧书。'), user('稳定')], captureBusinessIdentity: () => ({
    hostChatId: h.context.chatId, chatId: h.context.chatMetadata.qianqianjie.chatId,
    characterLocator: 'character.png', personaLocator: 'persona.png',
  }), utility: async options => {
    if (mode === 'summary') return { jsonData: { summary: '顾舟答应归还旧书。' } };
    markStarted(); await wait;
    const request = JSON.parse(options.taskMessages[0].content);
    return { jsonData: { floors: [{ floorKey: request.floors[0].floorKey, qianshi: { events: [{ key: 'event-1', title: '归还旧书', description: '顾舟答应归还旧书', status: 'planned', matter: true }], order: [] } }] } };
  } });
  await h.runtime.start();
  const target = h.runtime.getState().floors[0];
  await h.runtime.extractFloor(target.floorId, { analyzeState: false });
  const targetIdentity = h.runtime.captureBusinessIdentity();
  const originalStore = h.store.forIdentity(targetIdentity);
  const beforeMemoryId = h.foundationRuntime.getReachable().floorMemories.find(value => value.floorId === target.floorId).id;
  const plan = await h.runtime.prepareQianshiHistory(); mode = 'history';
  const run = h.runtime.startQianshiHistory(plan.planId); await started;
  h.context.chatId = 'new-host-chat';
  h.context.chatMetadata.qianqianjie.chatId = 'ffffffff-ffff-4fff-8fff-ffffffffffff';
  h.emit('CHAT_CHANGED');
  await waitFor(() => h.runtime.getQianshiSnapshot().status === 'not-ready');
  releaseHistory();
  const result = await run;
  assert.equal(result.status, 'completed', '切换浏览目标不取消原目标历史任务');
  assert.equal(h.runtime.getQianshiSnapshot().status, 'not-ready', '旧目标结果不投影到新页面');
  const stored = await originalStore.readReachable({ mode: 'runtime' });
  const updated = stored.floorMemories.find(value => value.floorId === target.floorId);
  assert.notEqual(updated.id, beforeMemoryId);
  assert.equal(updated.qianshiDelta.events[0].title, '归还旧书', '保存仍写回任务开始时的目标');
  const current = await h.store.readReachable({ mode: 'runtime' });
  assert.notEqual(current.root?.chatId, CHAT, '当前页面store仍指向新目标');
  originalStore.release();
});


test('手动刷新既成缺 integrity 尾删档经过完整读回恢复摘要与CSE，普通refresh只inspect', async () => {
  let h, reads = 0, failAnchorWrites = false;
  h = harness({ readOnlyLifecycle: true, modernAnchors: true,
    initialChat: [assistant('第一楼'), user('一'), assistant('第二楼'), user('二'), assistant('第三楼'), user('三')],
    foundationFetch: async () => { reads++; return { ok: true, json: async () => [{ chat_metadata: structuredClone(h.context.chatMetadata) }, ...structuredClone(h.context.chat)] }; },
    persistAnchors: async ({ chatId, bindings }) => {
      if (failAnchorWrites) throw Object.assign(new Error('模拟消息标识保存失败'), { code: 'V3_MESSAGE_ANCHOR_SAVE_FAILED' });
      for (const binding of bindings) h.context.chat[binding.messageIndex].extra = { ...(h.context.chat[binding.messageIndex].extra ?? {}), qianqianjie_floor: { schemaVersion: 1, chatId, floorId: binding.floorId } };
    },
    utility: options => options.systemPrompt === EXTRACTOR_SYSTEM_PROMPT ? { jsonData: { summary: '摘要', people: [{ name: '裴晚生' }] } } : { jsonData: { noMaterialChange: true } } });
  h.context.chatMetadata.integrity = 'complete';
  await h.runtime.start(); await h.runtime.startHistoricalRebuild();
  await waitFor(() => registeredGraphCaughtUp(h.runtime.getState()));
  const full = h.foundationRuntime.getReachable(), root = structuredClone(h.backend.records.get(`chat-${CHAT}/v3-root`));
  const entitySemantics = values => values.map(({ firstSeenFloorId, lastSeenFloorId, ...value }) => value);
  const preservedPrefix = structuredClone({ floors: full.floors.slice(0, 2), floorMemories: full.floorMemories.slice(0, 2),
    stateDeltas: full.stateDeltas.slice(0, 2), entities: entitySemantics(full.entities), baseline: full.baseline });
  const callCount = h.calls.length;
  delete h.context.chat[0].extra.qianqianjie_floor;
  failAnchorWrites = true;
  await h.runtime.refreshStatus({ preferCached: false });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  assert.equal(h.runtime.getState().lastExtractorError?.phase, 'anchor');
  assert.equal(h.runtime.getState().memorySyncStatus, 'error');
  failAnchorWrites = false;
  delete h.context.chatMetadata.integrity; h.context.chat.splice(4);
  await h.runtime.refreshStatus({ preferCached: false });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  assert.equal(reads, 0); assert.equal(h.runtime.getState().memorySyncStatus, 'needsReview');
  assert.deepEqual(h.backend.records.get(`chat-${CHAT}/v3-root`), root);
  await h.runtime.refreshStatus({ preferCached: false, recoverTailDeletion: true, reconcileFoundation: true });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  const after = h.runtime.getState(), cut = h.foundationRuntime.getReachable();
  assert.equal(reads, 1); assert.equal(after.memorySyncStatus, 'idle'); assert.equal(after.stableCount, 2);
  assert.equal(after.lastExtractorError, null); assert.equal(after.memorySyncError, null);
  assert.ok(h.context.chat[0].extra.qianqianjie_floor, '幸存前缀缺失的标识必须真实重试成功后才清除旧错误');
  assert.deepEqual({ floors: cut.floors, floorMemories: cut.floorMemories, stateDeltas: cut.stateDeltas,
    entities: entitySemantics(cut.entities), baseline: cut.baseline }, preservedPrefix, '恢复只回退已删除尾楼，旧前缀摘要、CSE、人物与基线保持不变');
  assert.deepEqual(cut.floorMemories, full.floorMemories.slice(0, 2));
  assert.deepEqual(cut.stateDeltas, full.stateDeltas.slice(0, 2));
  assert.equal(h.calls.length, callCount, '恢复不调用模型');

  delete h.context.chat[0].extra.qianqianjie_floor;
  failAnchorWrites = true;
  await h.runtime.refreshStatus({ preferCached: false });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  h.context.chat.splice(2);
  await h.runtime.refreshStatus({ preferCached: false, recoverTailDeletion: true, reconcileFoundation: true });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  assert.equal(h.runtime.getState().memorySyncStatus, 'error');
  assert.equal(h.runtime.getState().lastExtractorError?.phase, 'anchor');
  assert.equal(h.context.chat[0].extra.qianqianjie_floor, undefined, '幸存前缀保存仍失败时不得假报 idle');
  failAnchorWrites = false;
  await h.runtime.refreshStatus({ preferCached: false });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  assert.equal(h.runtime.getState().memorySyncStatus, 'idle');
  assert.ok(h.context.chat[0].extra.qianqianjie_floor, '后续保存恢复时沿用既有挂标重试并清除错误');

  delete h.context.chat[0].extra.qianqianjie_floor;
  failAnchorWrites = true;
  await h.runtime.refreshStatus({ preferCached: false });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  failAnchorWrites = false;
  h.context.chat.splice(0);
  await h.runtime.refreshStatus({ preferCached: false, recoverTailDeletion: true, reconcileFoundation: true });
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing');
  assert.equal(reads, 3);
  assert.equal(h.runtime.getState().stableCount, 0);
  assert.equal(h.runtime.getState().memorySyncStatus, 'idle');
  assert.equal(h.runtime.getState().lastExtractorError, null);
  assert.equal(h.runtime.getState().memorySyncError, null);
  assert.equal(h.calls.length, callCount, '连续尾删与删空恢复都不得调用模型');
});

test('旧 partial 有事件按已存档冷读，正文普通编辑后不回算也不自动补齐', async () => {
  const utility = options => {
      const request = JSON.parse(options.taskMessages[0].content);
      if (request.task !== 'extractFloorSemantics') return { jsonData: { noMaterialChange: true } };
      return { jsonData: { summary: '林岚在钟楼找到旧钥匙。', qianshi: { events: [
        { key: 'key-found', title: '找到旧钥匙', description: '林岚在钟楼找到旧钥匙。', status: 'occurred', matter: false },
        { key: 'key-used', title: '用旧钥匙打开钟楼侧门', description: '林岚用旧钥匙打开钟楼侧门。', status: 'occurred', matter: false },
      ], order: [{ before: 'key-found', after: 'key-used' }] } } };
    };
  const h = harness({ initialChat: [user('开始'), assistant('林岚在钟楼找到旧钥匙。'), user('稳定')], utility });
  await h.runtime.start();
  const floor = h.runtime.getState().floors[0];
  await h.runtime.extractFloor(floor.floorId, { analyzeState: false });
  const before = await h.store.readReachable({ mode: 'runtime' });
  const oldMemory = before.floorMemories.find(value => value.floorId === floor.floorId);
  const oldEvents = structuredClone(oldMemory.qianshiDelta.events);
  const oldRelations = structuredClone(oldMemory.qianshiDelta.relations);
  assert.equal(oldRelations.length, 1);
  const oldKey = `chat-${CHAT}/v3-floor-memory-${oldMemory.id}`, oldRecord = h.backend.records.get(oldKey);
  h.backend.records.set(oldKey, { ...oldRecord, data: { ...oldRecord.data,
    qianshiDelta: { ...oldRecord.data.qianshiDelta, status: 'partial', reason: 'legacy partial',
      historyReview: { rawFingerprint: oldMemory.sourceRawFingerprint, priorStatus: 'ready', priorReason: null,
        candidates: [{ candidateId: oldEvents[0].id, decision: 'pending', event: oldEvents[0], relations: [],
          recommendedEventId: null, matchBasis: [] }] } } } });
  const coldHarness = harness({ sharedBackend: h.backend, sharedContext: h.context, utility });
  await coldHarness.runtime.start();
  const cold = coldHarness.runtime.getQianshiSnapshot();
  assert.equal(cold.coverage.completeFloors, 1);
  assert.equal(cold.coverage.partialFloors, 0);
  assert.deepEqual(cold.events.map(({ id, title }) => ({ id, title })), oldEvents.map(({ id, title }) => ({ id, title })));
  assert.deepEqual(cold.relations.map(({ id, fromEventId, toEventId }) => ({ id, fromEventId, toEventId })),
    oldRelations.map(({ id, fromEventId, toEventId }) => ({ id, fromEventId, toEventId })), '重开后旧关系及引用 ID 不变');
  assert.deepEqual(cold.history.pendingReviews ?? [], [], '旧 historyReview 草稿不作为事实或用户待办恢复');
  assert.equal(coldHarness.runtime.confirmQianshiHistoryReview, undefined, 'runtime 不再暴露人工确认入口');
  const plan = await coldHarness.runtime.prepareQianshiHistory();
  assert.equal(plan.status, 'empty', '已有合法事件的旧档跳过补齐');
  const callsBeforeEdit = coldHarness.calls.length;
  const beforeFloor = coldHarness.runtime.getState().floors[0];
  coldHarness.context.chat[beforeFloor.messageIndex].mes = '林岚后来在钟楼找到那把旧钥匙。';
  coldHarness.emit('MESSAGE_EDITED', beforeFloor.messageIndex);
  await waitFor(() => coldHarness.foundationRuntime.getState().status === 'ready' && coldHarness.runtime.getQianshiSnapshot().status === 'ready');
  const afterEdit = await coldHarness.store.readReachable({ mode: 'runtime' });
  const editedMemory = afterEdit.floorMemories.find(value => value.floorId === floor.floorId);
  assert.deepEqual(editedMemory.qianshiDelta.events, oldEvents, '普通编辑保留原存千事事件，不自动重算');
  assert.deepEqual(editedMemory.qianshiDelta.relations, oldRelations, '普通编辑保留旧事件关系和端点 ID');
  assert.equal(coldHarness.calls.length, callsBeforeEdit, '普通编辑不调用模型');
  assert.equal((await coldHarness.runtime.prepareQianshiHistory()).status, 'empty', '刷新后的旧档仍跳过历史补齐');
});

test('千事事件物品编辑只改 object，保留文字、楼档其他字段与关系并进入后续检索召回', async () => {
  const utility = options => {
    const request = JSON.parse(options.taskMessages[0].content);
    if (request.task !== 'extractFloorSemantics') return { jsonData: { noMaterialChange: true } };
    return { jsonData: { summary: '两件事情的简短摘要。', qianshi: { events: [
      { key: 'start', title: '找到旧信', description: '林岚在桌上找到旧信。', status: 'occurred', matter: false, object: '旧信封' },
      { key: 'read', title: '读完旧信', description: '林岚读完旧信并收好。', status: 'occurred', matter: false },
    ], order: [{ before: 'start', after: 'read' }] } } };
  };
  const h = harness({ modernAnchors: true, initialChat: [user('开始'), assistant('林岚找到并读完一封旧信。'), user('稳定')], utility });
  await h.runtime.start();
  const floor = h.runtime.getState().floors[0];
  await h.runtime.extractFloor(floor.floorId, { analyzeState: false });
  const beforeGraph = await h.store.readReachable({ mode: 'runtime' });
  const beforeMemory = beforeGraph.floorMemories.find(value => value.floorId === floor.floorId);
  const event = beforeMemory.qianshiDelta.events[0], originalId = beforeMemory.id;
  const originalRelations = structuredClone(beforeMemory.qianshiDelta.relations);
  const baseline = structuredClone(beforeMemory);
  assert.equal(event.object, '旧信封', '既有 object 字符串按原样读取');
  const firstRecall = h.runtime.getQianshiRecall({ queryContext: { latestUserText: '旧信封' } });
  assert.deepEqual(firstRecall.eventIds, [event.id], '既有 object 字符串继续参与相关性召回');
  assert.match(firstRecall.text, /本轮千事资料来源截至：AI #1。/u, 'memory-runtime 普通候选入口保留所选来源楼范围');
  assert.equal(prepareQianshiCandidates(beforeGraph, { canonicalContent: '旧信封', includeEventContextCandidates: true }).request.some(value => value.object === '旧信封'), true,
    '既有 object 字符串继续进入后续事项候选');
  assert.equal(h.runtime.canEditQianshiEventText(event.id), true);
  const noOpRevision = beforeGraph.rootRevision;
  assert.deepEqual(await h.runtime.editQianshiEventText({ eventId: event.id,
    expected: { memoryId: beforeMemory.id, title: event.title, description: event.description, object: event.object },
    title: event.title, description: event.description, object: event.object }), { status: 'unchanged' });
  assert.equal((await h.store.readReachable({ mode: 'runtime' })).rootRevision, noOpRevision, '所有字段不变时零写');
  const sourceStateFloor = h.runtime.getState().floors[0], editedMessage = h.context.chat[sourceStateFloor.messageIndex];
  editedMessage.extra = { qianqianjie_floor: { schemaVersion: 1, chatId: CHAT, floorId: sourceStateFloor.floorId } };
  editedMessage.mes = '林岚找到并读完一封旧信，后来又确认信封来历。';
  if (editedMessage.swipes?.length) editedMessage.swipes[0] = editedMessage.mes;
  h.emit('MESSAGE_EDITED', sourceStateFloor.messageIndex);
  assert.equal((await h.foundationRuntime.refreshStatus()).status, 'ready', '正文编辑后的真实地基已稳定');
  await waitFor(() => h.runtime.getState().memorySyncStatus !== 'syncing' && h.runtime.getQianshiSnapshot().status === 'ready');
  const afterBodyEdit = await h.store.readReachable({ mode: 'runtime' });
  assert.equal(afterBodyEdit.floorMemories.find(value => value.floorId === floor.floorId).id, originalId,
    '正文普通编辑并稳定后，已有正式千事档案仍可用');
  await h.runtime.editQianshiEventText({ eventId: event.id, expected: { memoryId: beforeMemory.id, title: event.title, description: event.description, object: event.object }, title: event.title, description: event.description, object: '蓝皮手稿' });
  const afterGraph = await h.store.readReachable({ mode: 'runtime' });
  const afterMemory = afterGraph.floorMemories.find(value => value.floorId === floor.floorId);
  assert.notEqual(afterMemory.id, originalId);
  assert.equal(afterMemory.supersedes, originalId);
  const comparable = structuredClone(afterMemory);
  comparable.id = baseline.id; comparable.updatedAt = baseline.updatedAt; comparable.supersedes = baseline.supersedes;
  const edited = comparable.qianshiDelta.events.find(value => value.id === event.id);
  edited.object = event.object;
  delete comparable.qianshiDelta.manualEventOverrides;
  assert.deepEqual(comparable, baseline, '除 revision 头字段、目标事件 object 和独立人工标记外，FloorMemory 字段逐项不变');
  assert.deepEqual(afterMemory.qianshiDelta.manualEventOverrides, [{ eventId: event.id, object: '蓝皮手稿' }], '只记录人工改动的物品字段，不锁住状态');
  const savedEvent = afterMemory.qianshiDelta.events.find(value => value.id === event.id);
  assert.equal(savedEvent.sourceFloorId, event.sourceFloorId);
  assert.equal(savedEvent.title, event.title);
  assert.equal(savedEvent.description, event.description);
  assert.equal(savedEvent.object, '蓝皮手稿');
  assert.equal(h.runtime.getQianshiSnapshot().events.find(value => value.id === event.id).object, '蓝皮手稿', '正式快照显示新物品');
  assert.deepEqual(afterMemory.qianshiDelta.relations, originalRelations);
  assert.deepEqual(h.runtime.getQianshiSnapshot().relations.map(({ id, fromEventId, toEventId }) => ({ id, fromEventId, toEventId })),
    originalRelations.map(({ id, fromEventId, toEventId }) => ({ id, fromEventId, toEventId })), '原有关系端点仍在图中');
  const nextCandidates = prepareQianshiCandidates(afterGraph, { canonicalContent: '蓝皮手稿', includeEventContextCandidates: true });
  const nextCandidate = nextCandidates.request.find(value => value.candidateType === 'event' && value.title === event.title);
  assert.equal(nextCandidate?.object, '蓝皮手稿', '下一轮千事候选输入读到新物品');
  assert.deepEqual(h.runtime.getQianshiRecall({ queryContext: { latestUserText: '蓝皮手稿' } }).eventIds, [event.id], '相关性召回使用新 object 命中正式事件');
  await h.runtime.editQianshiEventText({ eventId: event.id, expected: { memoryId: afterMemory.id, title: event.title, description: event.description, object: '蓝皮手稿' }, title: event.title, description: event.description, object: null });
  const clearedGraph = await h.store.readReachable({ mode: 'runtime' });
  assert.equal(clearedGraph.floorMemories.find(value => value.floorId === floor.floorId).qianshiDelta.events.find(value => value.id === event.id).object, null, '空值清除 object');
  const beforeInvalid = clearedGraph.rootRevision;
  await assert.rejects(h.runtime.editQianshiEventText({ eventId: event.id, expected: { memoryId: clearedGraph.floorMemories.find(value => value.floorId === floor.floorId).id, title: event.title, description: event.description, object: null }, title: event.title, description: event.description, object: '超'.repeat(1001) }), { code: 'QIANSHI_TEXT_EDIT_INVALID' });
  await assert.rejects(h.runtime.editQianshiEventText({ eventId: event.id, expected: { memoryId: clearedGraph.floorMemories.find(value => value.floorId === floor.floorId).id, title: event.title, description: event.description, object: null }, title: event.title, description: event.description, object: 42 }), { code: 'QIANSHI_TEXT_EDIT_INVALID' });
  assert.equal((await h.store.readReachable({ mode: 'runtime' })).rootRevision, beforeInvalid, '非法 object 输入没有写入');
  await assert.rejects(h.runtime.editQianshiEventText({ eventId: event.id, expected: { memoryId: clearedGraph.floorMemories.find(value => value.floorId === floor.floorId).id, title: '旧基线', description: savedEvent.description, object: '蓝皮手稿' }, title: '覆盖', description: '不应写入', object: '覆盖' }), { code: 'QIANSHI_TEXT_EDIT_BASELINE_CHANGED' });
  const afterStaleAttempt = await h.store.readReachable({ mode: 'runtime' });
  assert.equal(afterStaleAttempt.floorMemories.find(value => value.floorId === floor.floorId).qianshiDelta.events.find(value => value.id === event.id).object, null);
  assert.equal(h.calls.filter(options => JSON.parse(options.taskMessages[0].content).task === 'extractFloorSemantics').length, 1, '编辑不调用模型');
});

test('千事文字编辑合并无关摘要修订且保留人工字段', async () => {
  const utility = options => {
    const request = JSON.parse(options.taskMessages[0].content);
    if (request.task !== 'extractFloorSemantics') return { jsonData: { noMaterialChange: true } };
    return { jsonData: { summary: '摘要。', qianshi: { events: [
      { key: 'fact', title: '旧事实', description: '原始经过。', status: 'occurred', matter: false },
    ], order: [] } } };
  };
  const h = harness({ initialChat: [user('开始'), assistant('旧事实。'), user('稳定')], utility });
  await h.runtime.start();
  const floor = h.runtime.getState().floors[0];
  await h.runtime.extractFloor(floor.floorId, { analyzeState: false });
  const memory = (await h.store.readReachable({ mode: 'runtime' })).floorMemories.find(value => value.floorId === floor.floorId);
  const event = memory.qianshiDelta.events[0];
  const competitor = harness({ sharedBackend: h.backend, sharedContext: h.context, utility });
  await competitor.runtime.start();
  const gate = h.backend.holdNextRootPut();
  const pendingEdit = h.runtime.editQianshiEventText({ eventId: event.id, expected: { memoryId: memory.id, title: event.title, description: event.description, object: event.object }, title: '迟到草稿', description: '过期修改。', object: event.object });
  await gate.started;
  await competitor.runtime.editSummary(floor.floorId, '并发摘要修订。');
  gate.release();
  await pendingEdit;
  const after = await h.store.readReachable({ mode: 'runtime' });
  const saved = after.floorMemories.find(value => value.floorId === floor.floorId);
  assert.equal(saved.qianshiDelta.events[0].title, '迟到草稿');
  assert.equal(saved.summary.userText, '并发摘要修订。');
});

test('聚合楼千事编辑保留成员归属，原文变化不否决人工字段', async () => {
  const utility = options => {
    const request = JSON.parse(options.taskMessages[0].content);
    if (request.task !== 'extractFloorSemantics') return { jsonData: { noMaterialChange: true } };
    return { jsonData: { summary: '聚合摘要。', qianshi: { events: [
      { key: 'member-event', title: '早楼找到徽章', description: '早楼原始经过。', status: 'occurred', matter: false },
    ], order: [] } } };
  };
  const h = harness({ modernAnchors: true, initialChat: [user('开始'), assistant('第一楼是徽章来源。'), user('继续'), assistant('第二楼汇总前情。'), user('稳定')], utility });
  await h.runtime.start();
  const [memberFloor, targetFloor] = h.runtime.getState().floors;
  await h.runtime.extractFloor(targetFloor.floorId, { analyzeState: false });
  const sourceGraph = await h.store.readReachable({ mode: 'runtime' });
  const target = sourceGraph.floorMemories.find(value => value.floorId === targetFloor.floorId);
  const sourceFloors = [memberFloor, targetFloor].map(value => sourceGraph.floors.find(floor => floor.id === value.floorId));
  const recordKey = `chat-${CHAT}/v3-floor-memory-${target.id}`, stored = h.backend.records.get(recordKey);
  const aggregate = validateFloorMemory({ ...target, sourceFloorIds: [memberFloor.floorId, targetFloor.floorId],
    sourceFloorSnapshots: sourceFloors.map(floor => ({ floorId: floor.id, canonicalContent: floor.content.canonicalContent,
      sourceUserInputSnapshot: structuredClone(target.sourceUserInputSnapshot), rawFingerprint: floor.content.rawFingerprint, storyClockSignature: '' })),
    qianshiDelta: { ...target.qianshiDelta, events: target.qianshiDelta.events.map(event => ({ ...event, sourceFloorId: memberFloor.floorId })) },
  }, { expectedChatId: CHAT });
  h.backend.records.set(recordKey, { ...stored, data: aggregate });
  const cold = harness({ sharedBackend: h.backend, sharedContext: h.context, utility });
  await cold.runtime.start();
  const memberIndex = sourceFloors[0].hostLocator.messageIndex, memberMessage = h.context.chat[memberIndex];
  memberMessage.extra = { qianqianjie_floor: { schemaVersion: 1, chatId: CHAT, floorId: memberFloor.floorId } };
  memberMessage.mes = '第一楼原文编辑后确认仍是徽章线索。';
  if (memberMessage.swipes?.length) memberMessage.swipes[0] = memberMessage.mes;
  cold.emit('MESSAGE_EDITED', memberIndex);
  assert.equal((await cold.foundationRuntime.refreshStatus()).status, 'ready', '聚合成员正文编辑后的真实地基已稳定');
  await waitFor(() => cold.runtime.getState().memorySyncStatus !== 'syncing' && cold.runtime.getQianshiSnapshot().status === 'ready');
  const event = cold.runtime.getQianshiSnapshot().events.find(value => value.id === target.qianshiDelta.events[0].id);
  assert.equal(event.sourceFloorId, memberFloor.floorId);
  await cold.runtime.editQianshiEventText({ eventId: event.id, expected: { memoryId: target.id, title: event.title, description: event.description, object: event.object }, title: '调整文字', description: '来源仍是第一楼。', object: event.object });
  const saved = await cold.store.readReachable({ mode: 'runtime' });
  const savedMemory = saved.floorMemories.find(value => value.floorId === targetFloor.floorId);
  assert.deepEqual(savedMemory.sourceFloorIds, [memberFloor.floorId, targetFloor.floorId]);
  assert.equal(savedMemory.qianshiDelta.events[0].sourceFloorId, memberFloor.floorId);
  assert.equal(savedMemory.qianshiDelta.events[0].title, '调整文字');
  const savedEvent = savedMemory.qianshiDelta.events[0];
  const sourceIndex = sourceFloors[0].hostLocator.messageIndex, changedMember = h.context.chat[sourceIndex];
  cold.backend.setBeforePut(async ({ collection, key, data }) => {
    if (collection !== `chat-${CHAT}` || !key.startsWith('v3-floor-memory-') || data.qianshiDelta?.events?.[0]?.title !== '不应覆盖') return;
    changedMember.mes = '第一楼原文再次编辑，徽章事实已移除。';
    if (changedMember.swipes?.length) changedMember.swipes[0] = changedMember.mes;
    cold.backend.setBeforePut(null);
  });
  const revisionBeforeReject = saved.rootRevision;
  await cold.runtime.editQianshiEventText({ eventId: savedEvent.id,
    expected: { memoryId: savedMemory.id, title: savedEvent.title, description: savedEvent.description, object: savedEvent.object }, title: '不应覆盖', description: '来源失效。', object: '不应覆盖' });

  const afterRejected = await cold.store.readReachable({ mode: 'runtime' });
  assert.ok(afterRejected.rootRevision > revisionBeforeReject);
  assert.equal(afterRejected.floorMemories.find(value => value.floorId === targetFloor.floorId).qianshiDelta.events[0].title, '不应覆盖');
  assert.equal(typeof cold.runtime.deleteQianshiEvent, 'function', '聚合事件删除复用所属楼的人工事务');
});

