 const workspace=await h.placeWorkspaceStore.read({chatId:CHAT},{fresh:true});assert.ok(workspace.data.foundation.facts.filter(f=>f.source.kind==='body').every(f=>f.source.quote.length<=2000&&f.source.quote===quote));
